def-group:

    {{{ oval_metadata("The " ~ full_name ~ " operating system file integrity tool must be configured to protect the integrity of the audit tools.", title="Configure AIDE to Verify the Audit Tools", rule_title=rule_title) }}}


{{%- if product == "ubuntu2004" %}}


          {{% for audit_tool in aide_audit_binaries -%}}

          {{% endfor %}}



          {{% for audit_tool in aide_audit_binaries if audit_tool != "audispd" -%}}

          {{% endfor %}}


{{%- else %}}
      {{% for audit_tool in aide_audit_binaries -%}}

      {{% endfor %}}
{{%- endif %}}




    {{% if 'rhel' not in product and 'almalinux' not in product and 'ubuntu' not in product and 'ol' not in families and product not in ['al2023', 'fedora'] %}}
    {{% if product in ['sle16'] %}}
    p+i+n+u+g+s+b+acl+selinux+sha512
    {{% else %}}
    p+i+n+u+g+s+b+acl+selinux+xattrs+sha512
    {{% endif %}}
    {{% else %}}
    ^p\+i\+n\+u\+g\+s\+b\+acl(|\+selinux)\+xattrs\+sha512$
    {{% endif %}}


  {{% for audit_tool in aide_audit_binaries %}}
    {{{ oval_test_aide_audit_tools(audit_tool) }}}
  {{%- endfor %}}
{{%- if product == "ubuntu2004" %}}

  {{#- CIS Ubuntu 20.04 v3.0.0 6.1.3 names six audit tools, without audispd,
      and reads the drop-in directory too. -#}}
  {{% for audit_tool in aide_audit_binaries if audit_tool != "audispd" %}}





    ^/etc/aide/aide\.conf(\.d/[^/]+)?$
    ^(?:/usr)?/sbin/{{{ audit_tool }}}\s+([^\n]+)$
    1

  {{% endfor %}}






    var_aide_audit_tools_cis


    true


{{%- endif %}}
